-- Nexmark q11 on clink, BLACKHOLE sink variant. User sessions: bids per
-- bidder per 10s-gap session window.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (auction BIGINT, bidder BIGINT, price BIGINT, channel VARCHAR, url VARCHAR, datetime BIGINT)
  WITH (connector='kafka', format='json', brokers='__BROKERS__', topic='nx-bid',
        group_id='clink-q11bh-bid', auto_offset_reset='earliest',
        event_time_column='datetime', watermark_lag_ms='4000');
CREATE TABLE sink_q11 (bidder BIGINT, bid_count BIGINT) WITH (connector='blackhole');
INSERT INTO sink_q11
SELECT bidder, COUNT(*) AS bid_count FROM bid GROUP BY SESSION(datetime, INTERVAL '10' SECOND), bidder;
